package nodecerttime

import (
	"compress/gzip"
	"context"
	"crypto/sha256"
	"crypto/x509"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"io"
	"reflect"
	"strconv"
	"strings"
	"talenro.local/platform/internal/nodecontrol/nodeissuer"
	"talenro.local/platform/internal/nodecontrol/statetimebinding"
	"testing"
)

// These are complete frozen Input JSON packets, losslessly encoded for source size.
// Generation and independent verification are preserved in the ignored evidence directory.
// No ordinary test generates keys, signs, reads external fixtures, or changes old testdata.
const certTimeFrozenInputs = ""
const certTimeFrozenManifest = ""

type certTimeManifest struct {
	Input                       string
	Raw                         map[string]string
	Certificate, Time           string
	CertificateError, TimeError string
}

func certTimeDecode(t testing.TB, text string, into any) {
	t.Helper()
	b, e := base64.StdEncoding.DecodeString(text)
	if e != nil {
		t.Fatal(e)
	}
	z, e := gzip.NewReader(strings.NewReader(string(b)))
	if e != nil {
		t.Fatal(e)
	}
	defer z.Close()
	b, e = io.ReadAll(z)
	if e != nil {
		t.Fatal(e)
	}
	if e = json.Unmarshal(b, into); e != nil {
		t.Fatal(e)
	}
}
func certTimeFixture(t testing.TB, name string) Input {
	t.Helper()
	var packets map[string]Input
	certTimeDecode(t, certTimeFrozenInputs, &packets)
	in, ok := packets[name]
	if !ok {
		t.Fatal("unknown frozen fixture", name)
	}
	return in
}
func certTimeHash(raw []byte) string { d := sha256.Sum256(raw); return hex.EncodeToString(d[:]) }
func certTimeJSONHash(t testing.TB, in any) string {
	t.Helper()
	b, e := json.Marshal(in)
	if e != nil {
		t.Fatal(e)
	}
	return certTimeHash(b)
}
func certTimeRawHashes(v reflect.Value, path string, out map[string]string) {
	if v.Kind() == reflect.Pointer {
		if !v.IsNil() {
			certTimeRawHashes(v.Elem(), path, out)
		}
		return
	}
	if v.Kind() == reflect.Struct {
		for i := 0; i < v.NumField(); i++ {
			certTimeRawHashes(v.Field(i), path+"."+v.Type().Field(i).Name, out)
		}
		return
	}
	if v.Kind() == reflect.Slice {
		if v.Type().Elem().Kind() == reflect.Uint8 {
			out[path] = certTimeHash(v.Bytes())
			return
		}
		for i := 0; i < v.Len(); i++ {
			certTimeRawHashes(v.Index(i), path+"["+strconv.Itoa(i)+"]", out)
		}
	}
}
func assertCertTimeLowerControls(t testing.TB, in Input) Summary {
	t.Helper()
	c, e := nodeissuer.Evaluate(context.Background(), in.Certificate)
	if c != nil {
		defer c.Clear()
	}
	if e != nil || c == nil {
		t.Fatal("issuer positive control", e)
	}
	tm, e := statetimebinding.Evaluate(context.Background(), in.Time)
	if tm != nil {
		defer tm.Clear()
	}
	if e != nil || tm == nil {
		t.Fatal("time positive control", e)
	}
	s := Summary{Certificate: c.Summary(), Time: tm.Summary()}
	if s.Certificate.Proof != nodeissuer.NodeLeafDirectIssuerSignatureBound || s.Time.Status != statetimebinding.ConditionalTimeEvidenceBound {
		t.Fatal("lower proof control")
	}
	return s
}
func TestCertTimeFixtureControls(t *testing.T) {
	var packets map[string]Input
	var manifest map[string]certTimeManifest
	certTimeDecode(t, certTimeFrozenInputs, &packets)
	certTimeDecode(t, certTimeFrozenManifest, &manifest)
	if len(packets) != 34 || len(manifest) != 34 {
		t.Fatal("frozen names/inventory")
	}
	for name, in := range packets {
		t.Run(name, func(t *testing.T) {
			m, ok := manifest[name]
			if !ok || certTimeJSONHash(t, in) != m.Input {
				t.Fatal("input manifest")
			}
			raw := map[string]string{}
			certTimeRawHashes(reflect.ValueOf(in), "Input", raw)
			certTimePayloadHashes(t, in, raw)
			ca, e := x509.ParseCertificate(in.Certificate.CA.DER)
			if e != nil {
				t.Fatal(e)
			}
			leaf, e := x509.ParseCertificate(in.Certificate.Leaf.DER)
			if e != nil {
				t.Fatal(e)
			}
			raw["Certificate.CA.TBS"] = certTimeHash(ca.RawTBSCertificate)
			raw["Certificate.Leaf.TBS"] = certTimeHash(leaf.RawTBSCertificate)
			if !reflect.DeepEqual(raw, m.Raw) {
				t.Fatal("raw/SPKI/TBS manifest")
			}
			c, ce := nodeissuer.Evaluate(context.Background(), in.Certificate)
			if c != nil {
				defer c.Clear()
			}
			tm, te := statetimebinding.Evaluate(context.Background(), in.Time)
			if tm != nil {
				defer tm.Clear()
			}
			if m.CertificateError != "" {
				if ce == nil || ce.Error() != m.CertificateError {
					t.Fatal("issuer negative control", ce)
				}
			} else {
				if ce != nil || c == nil || certTimeJSONHash(t, c.Summary()) != m.Certificate {
					t.Fatal("issuer positive/summary manifest", ce)
				}
			}
			if m.TimeError != "" {
				if te == nil || te.Error() != m.TimeError {
					t.Fatal("time negative control", te)
				}
			} else {
				if te != nil || tm == nil || certTimeJSONHash(t, tm.Summary()) != m.Time {
					t.Fatal("time positive/summary manifest", te)
				}
			}
		})
	}
}

func certTimePayloadHashes(t testing.TB, in Input, out map[string]string) {
	t.Helper()
	for n := 0; n < 2; n++ {
		rows, name := in.Time.Policy.Binding.Previous.Materials, "Previous"
		if n == 1 {
			rows = in.Time.Policy.Binding.Proposed.Materials.Materials
			name = "Proposed"
		}
		for i, row := range rows {
			pr := row.Raw
			var env struct {
				Payload string `json:"payload_b64url"`
			}
			if e := json.Unmarshal(pr, &env); e != nil {
				t.Fatal(e)
			}
			if env.Payload != "" {
				var e error
				pr, e = base64.RawURLEncoding.DecodeString(env.Payload)
				if e != nil {
					t.Fatal(e)
				}
				if certTimeHash(row.Raw) != hex.EncodeToString(row.Ref.Envelope[:]) {
					t.Fatal("frozen envelope reference")
				}
			}
			if certTimeHash(pr) != hex.EncodeToString(row.Ref.Payload[:]) {
				t.Fatal("frozen payload reference")
			}
			out[name+"["+strconv.Itoa(i)+"].Payload"] = certTimeHash(pr)
		}
	}
}
